1	import { layoutForLook } from "@/lib/generator/layout";
2	import type { DiaryPiece } from "./month";
3	
4	/**
5	 * How many cutouts a diary cell shows.
6	 *
7	 * A diary cell is ~45×54px on a 390px phone (7 columns, 7px gaps, 18px page
8	 * padding), so a five-piece look gives each garment about 20px and the flat-lay
9	 * reads as overlapping colour blobs. Three keeps distinct silhouettes while
10	 * still showing the outfit's palette — which is what a month grid is actually
11	 * scanned for ("which day was the camel one?"). The full look is one tap away.
12	 */
13	export const MAX_THUMB_PIECES = 3;
14	
15	type Candidate = { category: string; imageUrl: string };
16	
17	/** One upper-body piece, the bottoms, the shoes — in that reading order. */
18	const UPPER = ["Outerwear", "Tops"];
19	
20	/**
21	 * Choose and position the cutouts for one day's cell.
22	 *
23	 * Geometry comes from `layoutForLook`, the same deterministic templates the
24	 * full-size flat-lay uses, so a thumbnail is a scaled-down version of the look
25	 * the user tapped rather than a second, divergent layout system. The templates
26	 * are percentage-based, so they survive the shrink unchanged.
27	 */
28	export function thumbnailPieces(pieces: Candidate[]): DiaryPiece[] {
29	  // A piece the storage layer could not sign is dropped here rather than
30	  // rendered as <img src="">, which React treats as an error.
31	  const usable = pieces.filter((p) => Boolean(p.imageUrl));
32	
33	  const upper = UPPER.map((c) => usable.find((p) => p.category === c)).find(Boolean);
34	  const bottoms = usable.find((p) => p.category === "Bottoms");
35	  const shoes = usable.find((p) => p.category === "Shoes");
36	
37	  const chosen = [upper, bottoms, shoes].filter((p): p is Candidate => Boolean(p));
38	
39	  // A look made only of accessories has none of the three preferred slots, and
40	  // an empty cell would read as "nothing logged" for a day that was logged.
41	  if (chosen.length === 0) {
42	    chosen.push(...usable.slice(0, MAX_THUMB_PIECES));
43	  }
44	
45	  const capped = chosen.slice(0, MAX_THUMB_PIECES);
46	  const slots = layoutForLook(capped);
47	  return capped.map((p, i) => ({ imageUrl: p.imageUrl, slot: slots[i] }));
48	}
