1	import type { Slot } from "@/lib/generator/types";
2	
3	/** One cutout of a logged look, positioned by the flat-lay geometry. */
4	export type DiaryPiece = { imageUrl: string; slot: Slot };
5	
6	/**
7	 * A day's wear, as the diary needs it.
8	 *
9	 * `outfitId` is nullable because `wear_logs.outfit_id` is `ON DELETE SET NULL`
10	 * (migration `20260730090000`) — deleting an outfit degrades to "wear kept,
11	 * outfit forgotten" rather than a FK violation. Such a day still fills a cell;
12	 * it just cannot link anywhere.
13	 */
14	export type DayLog = { worn_on: string; outfitId: string | null; pieces: DiaryPiece[] };
15	
16	export type Cell = {
17	  key: string;
18	  day: number | null;
19	  inMonth: boolean;
20	  isToday: boolean;
21	  log?: DayLog;
22	};
23	
24	/** Monday-first, matching the design's weekday header. */
25	function mondayIndex(jsDay: number): number {
26	  return (jsDay + 6) % 7;
27	}
28	
29	function iso(year: number, month: number, day: number): string {
30	  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
31	}
32	
33	/**
34	 * The month grid. `month` is 1-12, not JS's 0-11 — the off-by-one there is a
35	 * classic and this boundary is the place to absorb it.
36	 *
37	 * `today` is passed in rather than read from the clock so the whole thing stays
38	 * pure and testable, and so the caller can supply the user's LOCAL date. Every
39	 * date in the diary is a local date key; comparing against a UTC one would
40	 * highlight the wrong cell all evening for eastern users.
41	 *
42	 * `Date.UTC` is used purely as calendar arithmetic — these are date keys, not
43	 * instants, so no timezone conversion is happening or wanted.
44	 */
45	export function buildMonth(year: number, month: number, today: string, logs: DayLog[]): Cell[] {
46	  const byDate = new Map(logs.map((l) => [l.worn_on, l]));
47	  const first = new Date(Date.UTC(year, month - 1, 1));
48	  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
49	  const lead = mondayIndex(first.getUTCDay());
50	
51	  const cells: Cell[] = [];
52	  for (let i = 0; i < lead; i++) {
53	    cells.push({ key: `lead-${i}`, day: null, inMonth: false, isToday: false });
54	  }
55	  for (let d = 1; d <= daysInMonth; d++) {
56	    const date = iso(year, month, d);
57	    cells.push({
58	      key: date,
59	      day: d,
60	      inMonth: true,
61	      isToday: date === today,
62	      log: byDate.get(date),
63	    });
64	  }
65	  while (cells.length % 7 !== 0) {
66	    cells.push({ key: `trail-${cells.length}`, day: null, inMonth: false, isToday: false });
67	  }
68	  return cells;
69	}
70	
71	/** `2026-07` → `July 2026`, for the header kicker. */
72	export function monthLabel(year: number, month: number): string {
73	  return new Intl.DateTimeFormat("en-GB", { month: "long", year: "numeric", timeZone: "UTC" })
74	    .format(new Date(Date.UTC(year, month - 1, 1)));
75	}
